import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.cZsgxozV.js";var i=JSON.parse(`{"title":"Encrypted markdown (.enc.md)","description":"","frontmatter":{},"headers":[],"relativePath":"custom-markdown/enc-md.md","filePath":"custom-markdown/enc-md.md"}`),a={name:`custom-markdown/enc-md.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="encrypted-markdown-enc-md" tabindex="-1">Encrypted markdown (<code>.enc.md</code>) <a class="header-anchor" href="#encrypted-markdown-enc-md" aria-label="Permalink to “Encrypted markdown (.enc.md)”">​</a></h1><p>Vault note files with the <strong><code>.enc.md</code></strong> extension store password-encrypted markdown. Plaintext never lives on disk; the editor holds plaintext only after unlock (session password cache).</p><h2 id="syntax-overview" tabindex="-1">Syntax (overview) <a class="header-anchor" href="#syntax-overview" aria-label="Permalink to “Syntax (overview)”">​</a></h2><ul><li>File name must end with <code>.enc.md</code> (case-insensitive).</li><li>Create via <strong>새 파일</strong> → format badge <strong><code>.enc.md</code></strong>, or type a name that already ends with <code>.enc.md</code>.</li><li>Body on disk is a single JSON object (AES-GCM wire format).</li></ul><h2 id="spec-interop" tabindex="-1">Spec (interop) <a class="header-anchor" href="#spec-interop" aria-label="Permalink to “Spec (interop)”">​</a></h2><h3 id="_1-file-name" tabindex="-1">1. File name <a class="header-anchor" href="#_1-file-name" aria-label="Permalink to “1. File name”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ENC_MD_NAME := STEM &quot;.enc.md&quot;   # STEM has no trailing registered create-file extension</span></span></code></pre></div><p>Detection: path/name lowercased ends with <code>.enc.md</code> (<code>isEncMdPath</code>).</p><p>Still treated as markdown for the editor viewer (last segment is <code>md</code>).</p><h3 id="_2-wire-body-canonical" tabindex="-1">2. Wire body (canonical) <a class="header-anchor" href="#_2-wire-body-canonical" aria-label="Permalink to “2. Wire body (canonical)”">​</a></h3><p>Same password-based payload as chat encrypted messages / <code>encryptData</code>:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ciphertext&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;base64&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;iv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;base64&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;salt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;base64&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li><code>salt</code>: 16 bytes, PBKDF2 (SHA-256, 100000 iterations) → AES-GCM-256 key</li><li><code>iv</code>: 12 bytes</li><li><code>ciphertext</code>: AES-GCM ciphertext (includes auth tag)</li></ul><p>UTF-8 plaintext markdown ↔ encrypt/decrypt with user password. Empty note at create time encrypts <code>&quot;&quot;</code>.</p><h3 id="_3-lifecycle" tabindex="-1">3. Lifecycle <a class="header-anchor" href="#_3-lifecycle" aria-label="Permalink to “3. Lifecycle”">​</a></h3><ol><li><strong>Create</strong> — Prompt password → write encrypted empty body → open unlocked in editor (in-memory session stores password for path only).</li><li><strong>Open</strong> — Read ciphertext → if no session password, PromptModal → decrypt → editor plaintext. Any leftover memo drafts for the path are deleted.</li><li><strong>Save</strong> — <strong>Manual save only</strong> (no 5s debounce, no tab/window auto-save, no idle remote auto-sync into the editor). Encrypt with session password (or prompt) → write JSON to vault. Failures do <strong>not</strong> write plaintext to IndexedDB drafts or pending-upload queues.</li><li><strong>Close tab</strong> — Drop in-memory password for that path.</li></ol><p>Password storage: <strong>RAM Map only</strong> — never localStorage / sessionStorage / IndexedDB.</p><h3 id="_4-non-goals" tabindex="-1">4. Non-goals <a class="header-anchor" href="#_4-non-goals" aria-label="Permalink to “4. Non-goals”">​</a></h3><ul><li>Server-side encryption / WebAuthn PRF for note files</li><li>Indexing ciphertext as searchable body (Advanced Search indexes filename only; body empty)</li><li>Automatic conversion between <code>.md</code> and <code>.enc.md</code></li><li>Auto-save, idle remote auto-sync into the editor, or offline draft recovery for <code>.enc.md</code> plaintext</li></ul><h2 id="options-attrs" tabindex="-1">Options / attrs <a class="header-anchor" href="#options-attrs" aria-label="Permalink to “Options / attrs”">​</a></h2><p>N/A (extension + JSON body only). Create-file badge metadata lives in <code>CREATE_FILE_FORMATS</code> (<code>id: &#39;enc.md&#39;</code>).</p><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Path</th></tr></thead><tbody><tr><td>Detect / encrypt / session password</td><td><code>src/utils/encMd.ts</code></td></tr><tr><td>Create-file formats + badges</td><td><code>src/utils/createFileFormats.ts</code>, <code>CreateItemModal.jsx</code></td></tr><tr><td>Path resolve</td><td><code>src/utils/createItemPath.ts</code></td></tr><tr><td>Crypto primitive</td><td><code>src/utils/crypto.js</code> (<code>encryptData</code> / <code>decryptData</code>)</td></tr><tr><td>Open (S3/WebDAV helper)</td><td><code>src/utils/storage/openPathFileFromBackend.js</code></td></tr><tr><td>Create / open / save UI</td><td><code>src/App.jsx</code> + <code>PromptModal</code></td></tr><tr><td>Tree lock icon</td><td><code>src/components/TreeNode.jsx</code></td></tr><tr><td>AS index skip body</td><td><code>src/utils/advancedSearch/engine.ts</code> via <code>indexableEncMdBody</code></td></tr><tr><td>Agent rule for new formats</td><td><code>.cursor/rules/create-file-formats.mdc</code></td></tr></tbody></table>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};